class Tables(HTMLParser):
 def __init__(self):super().__init__();self.rows=[];self.row=None;self.cell=None
 def handle_starttag(self,t,a):
  if t=='tr':self.row=[]
  if t in ['td','th'] and self.row is not None:self.cell=[]
 def handle_data(self,d):
  if self.cell is not None:self.cell.append(d)
 def handle_endtag(self,t):
  if t in ['td','th'] and self.cell is not None:self.row.append(re.sub(r'\s+',' ',' '.join(self.cell)).strip());self.cell=None
  if t=='tr' and self.row is not None:self.rows.append(self.row);self.row=None
t=Tables();t.feed((A/'primary/anastario-table1.html').read_text())
tr={r[0].replace(' ',''):r for r in t.rows if r}
groups=['California conventional','California organic','Mexico conventional','Mexico organic']
rows=[]
for el,analyte in [('Ni','Ni'),('Cd','Cd'),('Al','Al'),('Pb','Pb'),('As','tAs'),('Hg**','tHg'),('Cr','Cr'),('Sn','Sn')]:
 r=next(v for k,v in tr.items() if k.replace('*','')==el.replace('*',''))
 assert len(r)==11,(el,r)
 for i,group in enumerate(groups):
  cell=r[i+7]; nums=re.findall(r'\d+(?:\.\d+)?',cell);value=None if 'LOD' in cell else float(nums[0]);factor=1 if analyte=='tHg' else 1000
  rows.append(dict(id=f'hass-{analyte}-{i}',source_id=S,source_label='Anastario et al. 2025',analyte=analyte,material='Hass avocado pulp',group=group,region='United States retail; labelled '+group,period='November 2024–January 2025',n=6,sampling_unit='fruits in the labelled stratum; detected subset varies',basis='Dried mesocarp; source table units retained; no fresh-weight reconstruction',short_basis='Dried pulp',statistic='Geometric mean of detected values' if value is not None else 'Not detected',value=None if value is None else round(value*factor,8),finding='Not detected' if value is None else f'{value*factor:g} µg/kg',original_result=cell,reported_unit='ng/g' if analyte=='tHg' else 'µg/g',digest_lod_ug_L=r[1],detected_all_tissues=r[2],locator=f'Table 1, {el}, mesocarp, {group}; footnotes: detected samples only; Hg ng/g',censoring='Table means exclude non-detects. n>LOD column counts both tissues together, not the pulp stratum. Digest LOD is not a food concentration bound.',uncertainty='Six fruit per origin/practice stratum; origin based on commercial labels, no farm verification or paired soil. Missing CI (--) is not zero uncertainty. No grinder blank. Methods refer to digest concentrations while table presents tissue values: retain source-defined dried-tissue results without fresh-weight or exposure conversion.',conversion=f'{"ng/g = µg/kg" if factor==1 else "µg/g × 1000 = µg/kg"}; mass-unit conversion only.'))
# Peru Table 2 is parsed directly: never count the soil half as fruit replicates.
r=ET.parse(A/'primary/yoplac.xml').getroot();table=next(x for x in r.iter('table-wrap') if x.attrib.get('id')=='foods-15-00082-t002')
body=table.find('.//tbody');fruit=False;region=None
for row in body.findall('tr'):
 cells=[' '.join(c.itertext()).strip() for c in row]
 if cells and cells[0]=='Avocado':fruit=True;continue
 if not fruit:continue
 if 'Mean–S.D.' not in cells:continue
 j=cells.index('Mean–S.D.');region=cells[0] if j else region
 vals=cells[j+1:]
 for analyte,cell in zip(['tAs','Cd','Cr','tHg','Ni','Pb'],vals):
  ns=re.findall(r'\d+(?:\.\d+)?',cell);val=None if 'LOD' in cell else float(ns[0]);sd=None if val is None else float(ns[1])
  rows.append(dict(id=f'peru-{region}-{analyte}',source_id=Y,source_label='Yoplac-Navarro et al. 2026',analyte=analyte,material='Avocado pulp',group=region,region='Peru · '+region,period='January–September 2025',n=None,sampling_unit='fruit samples; regional independent count not explicit in primary main text',basis='Pulp dried at 70 °C for 24 h before digestion; no fresh-weight conversion',short_basis='Dried pulp',statistic='Source-reported regional mean' if val is not None else 'Below detection limit',value=None if val is None else round(val*1000,8),sd=None if sd is None else round(sd*1000,8),finding='Below detection limit' if val is None else f'{val*1000:g} µg/kg',original_result=cell,reported_unit='mg/kg',locator=f'Table 2 avocado block, {region}, {analyte}, Mean–S.D.; §2.1–2.3 sample preparation',censoring='Less-than and <LOD states preserved. Treatment of non-detects in regional means not explicit; no zero imputation. Abstract bounds: As/Cr 0.003 mg/kg; Cd/Hg/Ni/Pb 0.005 mg/kg. Per-row detection counts unavailable.',uncertainty='190 soil-plus-fruit samples, not 190 fruit observations. Separate per-region independent fruit counts not established here. Several reported Cd SDs exceed the listed within-region range; those summaries need author clarification and are not used for uncertainty modelling. All fruit mean superscripts share a; no significant regional difference is asserted.',conversion='mg/kg × 1000 = µg/kg; no moisture, species or preparation conversion.'))
frows=list(csv.DictReader((ROOT/'data/evidence/fda_tds_fy2018_2020_summary_by_food_analyte.csv').open()))
for r in frows:
 if r['tds_food_number']!='97' or r['metal_species'] not in ['Pb','Cd','tAs','tHg','Ni','Cr','U']:continue
 a=r['metal_species'];det=int(r['detected_n']);lo=r['min_detected_ppb'];hi=r['max_detected_ppb'];finding='Not detected' if det==0 else (f'{lo}–{hi} µg/kg' if lo!=hi else f'{hi} µg/kg')
 rows.append(dict(id='fda-'+a,source_id=F,source_label='FDA Total Diet Study FY2018–FY2020',analyte=a,material='Avocado, raw (FDA food 97)',group='FDA raw avocado composites',region='United States collection market',period='FY2018–FY2020',n=int(r['n']),sampling_unit='prepared-food composites',basis=r['basis'],short_basis='Raw prepared food',statistic='Detected range' if det else 'Not detected',value=None,finding=finding,original_result=f'{det}/{r["n"]} detected; detected range {lo or "none"}–{hi or "none"} ppb; reporting limit {r["reporting_limit_min_ppb_equivalent"]}–{r["reporting_limit_max_ppb_equivalent"]} ppb',reported_unit='ppb',locator=f'FDA SummaryElementsFY18-FY20 row {r["source_summary_xlsx_row"]}; food 97; {a}',detected=det,non_detect=int(r['non_detect_n']),reporting_limit=[float(r['reporting_limit_min_ppb_equivalent']),float(r['reporting_limit_max_ppb_equivalent'])],censoring='Detected range excludes non-detects. Zero-coded non-detects are reporting-limit bounds, not measured zeroes; no average reconstructed here.',uncertainty='Composites are not individual brands or growing-site samples. Origin, cultivar and farming practice are not supplied. Repeated analytes share the same composites.',conversion='ppb = µg/kg; no basis conversion.'))
bed=json.loads((A/'bedoya-samples.json').read_text())
for a in ['tAs','Cd','Pb']:
 samples=[r for r in bed['samples'] if r['analyte']==a];detects=[float(r['reported']) for r in samples if isinstance(r['reported'],(int,float))];bound={'tAs':100,'Cd':10,'Pb':38}[a]
 rows.append(dict(id='bedoya-'+a,source_id=B,source_label='Bedoya-Perales et al. 2023',analyte=a,material='Fuerte avocado pulp composites',group='Moquegua Fuerte pulp',region='Peru · Moquegua · Omate and Quinistaquillas',period='September 2021',n=8,sampling_unit='site-level pulp composites; at least 15 subsamples per composite',basis='Source-native edible pulp; moisture basis not explicitly labelled; no conversion',short_basis='Pulp; native basis',statistic='Detected value and reporting bounds' if detects else 'Below reporting bound',value=None,finding=f'{detects[0]*1000:g} µg/kg; 7 results <38 µg/kg' if detects else f'All <{bound} µg/kg',original_result='; '.join(f'sample {r["sample_id"]}: {r["reported"]} mg/kg ({r["locator"]})' for r in samples),reported_unit='mg/kg',locator='Figshare Dataset workbook; food-crop columns U (As), Z (Cd), AF (Pb); rows '+','.join(str(r['workbook_row']) for r in samples),censoring='All eight As <0.100 mg/kg; all eight Cd <0.010 mg/kg; seven Pb <0.038 mg/kg and one Pb 0.081 mg/kg. No zero substitution.',uncertainty='Convenience-selected mining-region sites in one harvest; not nationally representative. Eight composites are the independent sample units, not their subsamples. Unspecified moisture basis prevents numerical FDA/dried-pulp pooling or cultivar ranking.',conversion='mg/kg × 1000 = µg/kg; source-native basis retained.',source_samples=[dict(year=r['date'],result=str(r['reported'])+' mg/kg',locator=r['locator']+'; sample '+str(r['sample_id'])) for r in samples]))
save(A.relative_to(ROOT)/'occurrence-findings.json',{'rows':rows,'comparison_policy':'Within-study named group summaries only. No whole-page comparator override. No generic HMI pool combines raw FDA composites with dried tissue, geometric detected-only means and regional means with unclear censoring.','unit_note':'Summary rows are evidence summaries, never synthetic independent samples.'})

def p(text,keys):
 spans=[{'after':s,'source_keys':keys} for s in re.split(r'(?<=[.!?])\s+(?=[A-Z])',text)] if keys else []
 return dict(text=text,source_keys=keys,**({'citation_spans':spans} if keys else {}))
sections={
'summary':('Avocado overview',[
('Avocado pulp contains measurable nickel, cadmium and other total elements, but a raw-food composite result and a dried-tissue study answer different questions. FDA detected nickel and cadmium in all 27 raw avocado composites; lead appeared in one composite, while chromium and uranium were not detected at their respective reporting limits.',[F]),
('The strongest sourcing information is descriptive and specific to each metal. A small Hass study found a lower detected-only nickel geometric mean in California conventional pulp than in California organic pulp; Peru’s regional study found different patterns for mercury and other metals. These observations support checking the actual supplied pulp rather than treating a country or organic label as a guarantee.',[S,Y]),
('Keep peel, pulp, oil and finished recipes distinct. The available tissue comparison does not measure a household peeling reduction, and neither occurrence study establishes how much metal moves into avocado oil or a particular baby-food product.',[S,Y])]),
'identity':('Avocado pulp, peel and derivatives',[
('This page concerns the edible pulp of Persea americana, including Hass where the study identifies it. Anastario and colleagues separated mesocarp (pulp) from exocarp (peel), whereas the Peruvian study removed the peel before analysing dried pulp. Peel results are therefore useful tissue context and should not replace pulp measurements in a food-exposure calculation.',[S,Y]),
('FDA’s food 97 is raw avocado in the Total Diet Study prepared-food composite system. It is a different analytical material from dehydrated pulp; converting micrograms per gram into micrograms per kilogram changes the unit but does not restore the water removed during drying.',[F,S,Y]),
('Avocado oil, guacamole, seed preparations and mixed infant foods require their own measurements. No derivative-specific metal result or matched oil-extraction mass balance is established by these three source families.',[F,S,Y])]),
'occurrence':('Measured metals in avocado',[
('FDA’s 27 raw avocado composites contained detected nickel concentrations of 66–580 µg/kg and cadmium of 2.1–59 µg/kg. Lead was detected once at 12 µg/kg, total arsenic in six composites up to 50 µg/kg, and total mercury in three up to 1.3 µg/kg; the non-detected results retain their separate reporting limits.',[F]),
('The explorer also retains the original dried-pulp study summaries. Named comparisons use the same study, tissue, species, unit and statistic; they describe reported group summaries and do not supply a population reference band or safety grade.',[S,Y]),
('Arsenic, mercury and chromium here are total elements unless explicitly stated otherwise. These studies do not resolve inorganic arsenic, methylmercury or hexavalent chromium in the pulp.',[F,S,Y])]),
'pathways':('How metals reach avocado pulp',[
('The Peru study measured both cultivation soils and fruit, making soil-to-fruit transfer a relevant pathway, but a soil concentration cannot stand in for the edible-pulp result. Chromium was measurable in soils while all fruit results were below the reported detection limit, illustrating that tissue transfer differs among elements.',[Y]),
('The Hass pilot generally found higher element concentrations in peel than pulp, including aluminium and mercury. The authors discuss external exposure and tissue transport as possible explanations; because fruit was commercially purchased without paired farm soils, those mechanisms were not distinguished experimentally.',[S]),
('Mining, irrigation water and agricultural inputs are plausible contributors discussed by the Peruvian authors, who recommend monitoring soil, water and fruit. These observations do not establish that a particular retail avocado acquired nickel from volcanic soil or that organic production itself caused a measured difference.',[Y,S])]),
'variation':('Which origins and types appear lower?',[
('In the 24-fruit Hass pilot, the detected-only pulp nickel geometric means were 0.10 µg/g for California conventional, 0.58 for California organic, 0.11 for Mexico conventional and 0.16 for Mexico organic. California conventional was lowest within these four labelled groups; each group contained six fruit, and the source provides no verified farm provenance or causal farming-system comparison.',[S]),
('The same group did not minimize every element. The lowest reported pulp mercury geometric mean was California organic at 1.53 ng/g, compared with 2.57 for California conventional, 1.66 for Mexico conventional and 2.12 for Mexico organic; cadmium means were 0.01–0.02 µg/g, with overlapping intervals. Organic and conventional labels therefore do not provide a consistent all-metal ranking.',[S]),
('Within Peru, Cusco had the lowest reported mercury mean at 0.005 mg/kg in dried pulp, compared with 0.167 in Lima. Amazonas, Ancash, Cusco and Huancavelica had below-detection summaries for arsenic, cadmium, nickel and lead, so they cannot be ordered as measured zeroes. Regional fruit counts and the treatment of non-detects in means are not explicit in the main text, several cadmium dispersion summaries need clarification, and the table does not establish a statistically significant fruit-region difference. These are leads for origin-linked monitoring, not a reliable cleanest-region preference.',[Y])]),
'processing':('What preparation and processing can establish',[
('Both research studies removed the peel before measuring pulp; the Hass study also measured the separated peel. Its higher peel concentrations for several elements establish a tissue difference, but there was no intact-fruit versus peeled edible-portion intervention or mass-balance experiment from which to calculate a removal percentage.',[S,Y]),
('Dehydration, acid digestion and laboratory heating prepared samples for elemental analysis. They were not trials of cooking, soaking or household washing, and they provide no validated percentage reduction for those practices.',[S,Y]),
('The lipid content of avocado does not establish a metal concentration in its extracted oil. A useful oil comparison would require matched pulp, oil, residual fractions and extraction yield; guacamole and purée likewise need recipe-specific measurements rather than a transfer of the raw-pulp number.',[S,Y])]),
'controls':('Controls from cultivation to lot acceptance',[
('The Peruvian authors recommend regular soil and water analyses, attention to agrochemical quality and monitoring fruit before harvest. These are preventive and detection controls supported as recommendations, not intervention trials demonstrating that a named treatment lowered fruit concentrations by a particular amount.',[Y]),
('At procurement and release, the variation in measured pulp and the method comparison support a practical inference: sample the relevant lot and confirm decision-relevant trace metals with a suitable laboratory method. Portable X-ray fluorescence correlated with laboratory measurements for selected abundant elements, but the study does not validate it as a substitute for trace-metal release testing.',[S]),
('The stage-led table distinguishes the authors’ cultivation recommendations from this proposed analytical control. Neither entry implies removal of contamination already present in the edible pulp; quantitative agronomic, processing and home-preparation effects remain unresolved.',[Y,S])]),
'tradeoffs':('Control trade-offs and interpretation',[
('Selecting the lowest nickel group in the Hass pilot would not select the lowest mercury group. This is why a supplier specification needs the analytes relevant to the actual pulp and product, rather than a single organic, regional or low-metal label.',[S]),
('Peel and pulp have different profiles, so testing a peel-rich whole-fruit homogenate could misrepresent the edible material. Conversely, a pulp result cannot establish suitability of a seed powder, peel extract or oil; avoiding one mismatch does not resolve the others.',[S,Y]),
('Monitoring can identify a problem and guide sourcing, but these sources do not quantify its cost, waste burden, yield effect or commercial reduction performance. The proposed lot-testing approach should be understood as verification, not a proven decontamination benefit.',[S,Y])]),
'testing':('Testing the material that will be eaten',[
('The Hass study used ICP-MS after acid digestion and compared results with portable X-ray fluorescence. The strongest pulp calibration relationships were for potassium, calcium and zinc; limited variability prevented calibration for several trace elements, including nickel and chromium. A successful signal for an abundant nutrient therefore does not validate a screening device for every contaminant.',[S]),
('Reporting limits change what a non-detect can mean. FDA found no chromium in 27 raw avocado composites at a 50 µg/kg reporting limit, whereas the Peru paper reported all dried-pulp chromium below 0.003 mg/kg. These are different materials and analytical bounds; neither supports a measured concentration of zero or a claim about hexavalent chromium.',[F,Y]),
('Ask for the edible fraction, preparation, concentration basis, analyte species, reporting limits and sample plan with a lot result. This is a proposed reporting requirement derived from the mismatches visible here; it does not turn a single test or composite into proof of an entire region’s quality.',[F,S,Y])]),
'procurement':('Using evidence in avocado procurement',[
('The useful sourcing result is metal-specific: California conventional pulp had the lowest observed nickel geometric mean in the four-group Hass pilot, while California organic had the lowest mercury mean. The comparison is small and label-based; it supports keeping origin and farming practice in traceability records, not accepting or rejecting a country solely from these means.',[S]),
('Peru’s censored regional results identify monitoring questions rather than a fully ordered supplier list. A supplier proposing a lower-contamination region should provide comparable edible-pulp measurements from independent lots, with seasonal coverage, detection limits and fresh- or dry-weight basis clearly identified.',[Y]),
('FDA collection-market composites cannot resolve growing origin, cultivar or organic practice. A procurement claim about those attributes must come from origin-linked measurements, and a specification for oil or a finished recipe must use that purchased material’s own evidence.',[F,S,Y])]),
'product':('From pulp measurements to dietary exposure',[
('A concentration is only one input to exposure: the edible amount, consumption pattern and chemical species also matter. FDA raw avocado results describe sampled food composites; dried-pulp summaries need a justified moisture conversion before they can be used as fresh-fruit intake inputs.',[F,S,Y]),
('The Peruvian paper’s health-risk calculations depend on its assumed intake and body-weight distributions and on its analytical concentration basis. They are study-model outputs rather than evidence that an individual serving, a child’s product or every avocado lot is safe; this page does not derive a weekly allowance from them.',[Y]),
('Raw pulp does not define the concentration in a baby-food pouch, guacamole or extracted oil. Finished-product measurements, formulation and intended population are needed before making those comparisons; total arsenic and total mercury should not silently become specific toxicological species.',[F,S,Y])]),
'assessment':('Evidence review and requirements',[
('The quantitative core contains FDA’s raw-food composites and two primary dried-pulp studies, retaining their distinct sample units, bases and summaries. The Hass pilot is small and commercially labelled; the Peru study has unresolved regional fruit denominators, censoring conventions and several dispersion inconsistencies. These limitations constrain sourcing and exposure interpretation.',[F,S,Y]),
('The legacy FSA avocado composite and WHO arsenic summaries remain unresolved candidates for this assessment. Their preparation, primary values and censoring need reconciliation before a numerical result or species-specific conclusion is added; incomplete extraction is not a finding that evidence is absent.',[]),
('No current jurisdiction-specific maximum level or legal-compliance conclusion is established here. Study-author references to benchmarks are not substituted for a dated primary-instrument check covering the exact food, analyte, edible fraction and basis.',[])])}

faq=[
('ING-FAQ-01','occurrence','What heavy metals have been measured in avocado?','Nickel, cadmium, lead, total arsenic, total mercury and total chromium appear in the selected analytical sources, with aluminium and tin also assessed in the Hass pilot and uranium in FDA’s data. Detection differs by analyte and source; a measured panel does not mean every sample contains every metal.',[F,S,Y]),
('ING-FAQ-02','pathways','How do metals get into avocado pulp?','The soil–fruit study makes uptake and tissue transfer relevant, while the peel–pulp pilot identifies different tissue profiles. Neither design isolates the source of a particular retail fruit’s contamination; external deposition, soil and agricultural inputs should not be assigned causal percentages.',[S,Y]),
('ING-FAQ-03','variation','Is organic avocado free from heavy metals?','No: the Hass pilot measured metals in organic as well as conventional fruit. California organic pulp had a higher nickel geometric mean than California conventional pulp but a lower mercury mean; these small labelled groups do not establish a causal effect of organic practice.',[S]),
('ING-FAQ-04','variation','Is Hass lower in metals than other avocado varieties?','The retail pilot tested Hass only, while the regional Peru comparison does not establish a matched cultivar ranking. It cannot support calling Hass cleaner than Fuerte, Bacon or another variety.',[S,Y]),
('ING-FAQ-05','variation','Which origin had the lowest measured nickel?','California conventional pulp had the lowest detected-only geometric mean among four Hass origin/practice groups, at 0.10 µg/g on the study’s dried-tissue basis. Mexico conventional was 0.11, Mexico organic 0.16 and California organic 0.58; six fruit per group and labelled provenance limit generalization.',[S]),
('ING-FAQ-06','processing','Is avocado oil lower in heavy metals than the pulp?','These sources do not measure matched avocado oil and pulp or an extraction mass balance. An oil concentration and removal percentage therefore remain unknown; lipid content alone does not establish a cleaner derivative.',[S,Y]),
('ING-FAQ-07','product','Do these numbers tell me whether my avocado is safe?','They describe sampled materials and study summaries, not your lot or individual exposure. A relevant assessment also needs the consumed amount, chemical species and matching concentration basis; the Peruvian risk model is conditional on its own assumptions.',[F,Y]),
('ING-FAQ-08','assessment','Are the study benchmarks current legal limits for my product?','A study’s benchmark comparison is not a verified current legal determination for your product. This assessment leaves that jurisdiction-, analyte- and food-specific check unresolved rather than transferring a fresh-fruit or fish benchmark to another material.',[S,Y]),
('ING-FAQ-09','processing','How much metal does peeling an avocado remove?','A numerical removal fraction is not established here. Higher peel concentrations for several elements are tissue observations; without intact-fruit and edible-pulp mass balance, they cannot become a household peeling reduction percentage.',[S]),
('ING-FAQ-10','testing','Does total arsenic mean inorganic arsenic?','No: the selected pulp studies report total arsenic without resolving its chemical species. FDA’s avocado panel also supplies total arsenic, so none of those totals should be relabelled inorganic arsenic.',[F,S,Y]),
('ING-FAQ-11','identity','Can I use peel results to estimate the metals in edible pulp?','Use the separately measured pulp when that is what will be eaten. The Hass pilot found higher peel concentrations for several elements, so substituting peel or whole-fruit values would change the material being described.',[S]),
('ING-FAQ-14','processing','Does cooking have a demonstrated metal-removal effect in avocado?','No household cooking intervention was established in these sources. Laboratory drying and heated acid digestion are analytical preparation steps, not evidence of a reduction in the food you eat.',[S,Y]),
('ING-FAQ-16','product','How much avocado is safe to eat each week?','These occurrence sources do not establish a universal weekly allowance. A calculation would need a justified edible-food concentration, consumption and body-weight context, chemical species where relevant, and applicable health guidance; an average from dried pulp is not that calculation.',[F,Y]),
('AVO-FAQ-01','testing','Does a non-detect mean the metal is absent?','No: it means the result was below the method’s stated reporting or detection limit. FDA’s raw-avocado chromium bound was 50 µg/kg and uranium bound 1 µg/kg; neither is a measured zero.',[F]),
('AVO-FAQ-02','variation','Did the lowest-nickel group also have the lowest mercury?','No: California conventional had the lowest nickel geometric mean in the Hass pilot, while California organic had the lowest mercury mean at 1.53 ng/g. A single group cannot be described as lowest across all metals from these data.',[S]),
('AVO-FAQ-03','testing','Can portable X-ray fluorescence replace laboratory trace-metal testing?','The pilot supports further screening research, not a general substitution. Pulp calibration was strongest for potassium, calcium and zinc, and several trace elements could not be calibrated because variability was limited.',[S]),
('AVO-FAQ-04','testing','Were there 190 independent avocado samples in the Peru study?','The reported 190 samples include soil and fruit together. The main text does not explicitly provide a separate regional fruit denominator, so this assessment does not count all 190 as fruit observations or publish inferred per-region fruit counts.',[Y]),
('AVO-FAQ-05','controls','What can growers do while intervention effect sizes remain unknown?','The Peruvian authors recommend regular soil and water analysis, agrochemical quality controls and pre-harvest fruit monitoring. These are recommendations to prevent or detect contamination; this study did not test their percentage effect on avocado pulp.',[Y])]
sections['occurrence'][1].append(('The Moquegua open dataset separately reports eight Fuerte pulp composites: all arsenic results were below 0.100 mg/kg and all cadmium below 0.010 mg/kg; lead was 0.081 mg/kg in one composite and below 0.038 in seven. The workbook identifies pulp and atomic absorption analysis but does not explicitly label moisture basis, so these data retain their source-native basis without a cultivar or fresh-weight ranking.',[B]))
sections['variation'][1].append(('Fuerte pulp from Moquegua provides a separate cultivar observation, not a matched Hass comparison: it was sampled at different sites, in a different year, with different reporting bounds and an incompletely labelled moisture basis. Its censored values cannot establish that Fuerte is lower than Hass or that one Peruvian district is reliably cleaner.',[B,S]))
sections['assessment'][1][1]=('The FSA report’s legacy page returned Gone and its official report file returned Not Found during recovery. WHO avocado summaries require raw-row and duplicate-region reconciliation; a Taiwan edible-oil primary record also remains access-blocked. A Kaduna paper was retrieved, but it does not clearly identify pulp-only preparation, so its dried-avocado values are held outside the edible-pulp table. These are unfinished evidence assessments rather than findings that data are absent.',[I])
for index,item in enumerate(faq):
 if item[0]=='ING-FAQ-04':faq[index]=(item[0],item[1],item[2],'No matched cultivar ranking is established. The retail pilot measured Hass, while the Moquegua dataset separately measured eight Fuerte pulp composites; site selection, year, method, reporting bounds and incompletely labelled moisture basis prevent a defensible Hass-versus-Fuerte ordering.',[S,B])
 if item[0]=='ING-FAQ-06':faq[index]=(item[0],item[1],item[2],'An existing Taiwan edible-oil study is a relevant avocado-oil candidate, but its primary avocado row could not be verified in this assessment. The pulp studies contain no matched extraction mass balance, so an oil-versus-pulp reduction percentage remains unresolved.',[S,Y])
